/* SESÉ - Relatório Excel e ordenação por modelo/tamanho - 2026-08-12 */
(() => {
  "use strict";

  const collator = new Intl.Collator("pt-BR", {
    usage: "sort",
    sensitivity: "base",
    ignorePunctuation: true,
    numeric: true
  });

  const sizeRanks = new Map([
    ["pppp", 10], ["4xp", 10], ["4xs", 10],
    ["ppp", 20], ["3xp", 20], ["3xs", 20],
    ["pp", 30], ["xp", 30], ["xs", 30],
    ["p", 40], ["s", 40],
    ["m", 50],
    ["g", 60], ["l", 60],
    ["gg", 70], ["2g", 70],
    ["xg", 80], ["eg", 80], ["xl", 80], ["g1", 80],
    ["xgg", 90], ["xxg", 90], ["egg", 90], ["exg", 90], ["xxl", 90], ["g2", 90],
    ["xxxg", 100], ["eggg", 100], ["xxxl", 100], ["g3", 100],
    ["xxxxg", 110], ["xxxxl", 110], ["g4", 110]
  ]);

  function normalize(value) {
    return String(value ?? "")
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  }

  function compareText(left, right) {
    return collator.compare(String(left ?? "").trim(), String(right ?? "").trim());
  }

  function normalizedSize(value) {
    return normalize(value).replace(/^(?:tamanho|tam|numero|num|n)\s+/, "").trim();
  }

  function sizeKey(value) {
    const normalized = normalizedSize(value);
    if (!normalized || ["nao informado", "sem tamanho", "sem numeracao"].includes(normalized)) {
      return { family: 9, primary: Number.POSITIVE_INFINITY, secondary: Number.POSITIVE_INFINITY, text: "" };
    }
    if (sizeRanks.has(normalized)) {
      return { family: 0, primary: sizeRanks.get(normalized), secondary: 0, text: normalized };
    }
    const numberedLarge = normalized.match(/^g\s*(\d+)$/);
    if (numberedLarge) {
      return { family: 0, primary: 70 + (Number(numberedLarge[1]) * 10), secondary: 0, text: normalized };
    }
    const numericParts = normalized.match(/\d+(?:[.,]\d+)?/g);
    if (numericParts && /^\d+(?:[.,]\d+)?(?:\s+\d+(?:[.,]\d+)?)*$/.test(normalized)) {
      return {
        family: 1,
        primary: Number(numericParts[0].replace(",", ".")),
        secondary: numericParts[1] ? Number(numericParts[1].replace(",", ".")) : 0,
        text: normalized
      };
    }
    if (["unico", "unica", "universal", "padrao"].includes(normalized)) {
      return { family: 8, primary: 0, secondary: 0, text: normalized };
    }
    return { family: 2, primary: 0, secondary: 0, text: normalized };
  }

  function compareSizes(left, right) {
    const a = sizeKey(left);
    const b = sizeKey(right);
    return a.family - b.family || a.primary - b.primary || a.secondary - b.secondary || compareText(a.text, b.text);
  }

  function sizeFromDescription(description) {
    const text = String(description ?? "").trim();
    const declared = text.match(/(?:^|\s|[-–—|/])(?:tamanho|tam|numero|num|n[º°.]?)\s*[:.-]?\s*([a-z0-9.,/-]+)\s*$/i);
    if (declared) return declared[1];
    const finalToken = text.match(/(?:\s|[-–—|/])([a-z]{1,5}\d?)\s*$/i);
    if (!finalToken) return "";
    const token = normalizedSize(finalToken[1]);
    return sizeRanks.has(token) || /^g\s*\d+$/.test(token) ? finalToken[1] : "";
  }

  function sortSize(material) {
    const configured = material?.size;
    return sizeKey(configured).family !== 9 ? configured : sizeFromDescription(material?.description);
  }

  function descriptionBase(material) {
    const description = String(material?.description ?? "").trim();
    const detectedSize = sortSize(material);
    let base = description.replace(/\s*[-–—|/]?\s*(?:tamanho|tam|numero|num|n[º°.]?)\s*[:.-]?\s*[a-z0-9.,/-]+\s*$/i, "").trim();
    if (detectedSize) {
      const escaped = String(detectedSize).trim().replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      if (escaped) base = base.replace(new RegExp(`(?:\\s*[-–—|/]\\s*|\\s+)${escaped}\\s*$`, "i"), "").trim();
    }
    return base || description;
  }

  function compareMaterials(left, right) {
    return compareText(descriptionBase(left), descriptionBase(right))
      || compareSizes(sortSize(left), sortSize(right))
      || compareText(left?.description, right?.description)
      || compareText(left?.code, right?.code)
      || compareText(left?.manufacturer, right?.manufacturer)
      || compareText(left?.id, right?.id);
  }

  function sortedMaterials() {
    return [...state.materials].sort(compareMaterials);
  }

  function toast(message, isError = false) {
    if (typeof showToast === "function") showToast(message, isError);
  }

  function exportStockReportExcelPatch() {
    const button = document.getElementById("exportStockReportExcel");
    if (!button) return;
    const originalLabel = button.textContent;
    button.disabled = true;
    button.textContent = "Gerando Excel...";
    try {
      if (typeof XLSX === "undefined") throw new Error("Biblioteca XLSX indisponível.");
      const materials = sortedMaterials();
      const generatedAt = new Date().toLocaleString("pt-BR");
      const totalUnits = materials.reduce((sum, material) => sum + (Number(material.stock) || 0), 0);
      const zeroed = materials.filter(material => Number(material.stock) === 0).length;
      const critical = materials.filter(material => typeof materialStatus === "function" && materialStatus(material).key === "critical").length;
      const rows = [
        ["RELATÓRIO DE ESTOQUE DE MATERIAIS", "", "", "", "", "", "", "", "", ""],
        ["Unidade", state.settings.unit || "Gestão de EPI", "", "", "", "Emissão", generatedAt, "", "", ""],
        ["Endereço", state.settings.address || "Não informado", "", "", "", "Responsável", state.settings.responsible || "Não informado", "", "", ""],
        [],
        ["ITENS CADASTRADOS", materials.length, "TOTAL EM ESTOQUE", totalUnits, "ESTOQUE CRÍTICO", critical, "SALDO ZERADO", zeroed, "", ""],
        [],
        ["#", "Código", "Descrição", "Categoria", "Tamanho", "CA", "Lote", "Localização", "Saldo", "Estoque mínimo"]
      ];
      materials.forEach((material, index) => rows.push([
        index + 1,
        material.code || "",
        typeof upperText === "function" ? upperText(material.description || "") : String(material.description || "").toUpperCase(),
        material.category || "",
        material.size || "",
        material.ca || "",
        material.lot || "",
        material.location || "",
        Number(material.stock) || 0,
        typeof hasConfiguredMinimum === "function" && hasConfiguredMinimum(material) ? Number(material.minimum) : ""
      ]));
      rows.push(["", "", "", "", "", "", "", "TOTAL GERAL EM ESTOQUE", totalUnits, ""]);

      const sheet = XLSX.utils.aoa_to_sheet(rows);
      const headerRowIndex = 6;
      const lastRowIndex = rows.length - 1;
      sheet["!merges"] = [
        XLSX.utils.decode_range("A1:J1"),
        XLSX.utils.decode_range("B2:E2"),
        XLSX.utils.decode_range("G2:J2"),
        XLSX.utils.decode_range("B3:E3"),
        XLSX.utils.decode_range("G3:J3")
      ];
      sheet["!autofilter"] = {
        ref: XLSX.utils.encode_range({ r: headerRowIndex, c: 0 }, { r: Math.max(headerRowIndex, lastRowIndex - 1), c: 9 })
      };
      sheet["!freeze"] = { xSplit: 0, ySplit: headerRowIndex + 1 };
      sheet["!cols"] = [
        { wch: 7 }, { wch: 16 }, { wch: 42 }, { wch: 30 }, { wch: 14 },
        { wch: 16 }, { wch: 18 }, { wch: 28 }, { wch: 12 }, { wch: 18 }
      ];
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, sheet, "RELATÓRIO ESTOQUE");
      XLSX.writeFile(workbook, `relatorio_estoque_materiais_${new Date().toISOString().slice(0, 10)}.xlsx`);
      toast("Relatório Excel gerado em ordem alfabética e por tamanho.");
    } catch (error) {
      console.error("Falha na geração do relatório Excel", error);
      toast("Não foi possível gerar o relatório Excel.", true);
    } finally {
      button.disabled = false;
      button.textContent = originalLabel;
    }
  }

  function exportMaterialsSortedPatch() {
    try {
      if (typeof XLSX === "undefined") throw new Error("Biblioteca XLSX indisponível.");
      const rows = [["Código", "Descrição", "Tamanho", "Fabricante", "Categoria", "Número do CA", "Validade do CA", "Lote", "Validade do lote", "Saldo", "Estoque mínimo", "Vida útil em dias", "Localização", "Observações"]];
      sortedMaterials().forEach(item => rows.push([
        item.code,
        item.description,
        item.size || "",
        item.manufacturer || "",
        item.category,
        item.ca,
        item.caValidity,
        item.lot,
        item.lotValidity,
        Number(item.stock),
        typeof hasConfiguredMinimum === "function" && hasConfiguredMinimum(item) ? Number(item.minimum) : "",
        typeof hasLifetime === "function" && hasLifetime(item.lifetime) ? Number(item.lifetime) : "",
        item.location || "",
        item.notes || ""
      ]));
      const sheet = XLSX.utils.aoa_to_sheet(rows);
      sheet["!autofilter"] = { ref: sheet["!ref"] };
      sheet["!freeze"] = { xSplit: 0, ySplit: 1 };
      sheet["!cols"] = [
        { wch: 15 }, { wch: 36 }, { wch: 16 }, { wch: 26 }, { wch: 27 },
        { wch: 16 }, { wch: 18 }, { wch: 18 }, { wch: 19 }, { wch: 12 },
        { wch: 18 }, { wch: 20 }, { wch: 24 }, { wch: 40 }
      ];
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, sheet, "MATERIAIS");
      XLSX.writeFile(workbook, `materiais_epi_sese_${new Date().toISOString().slice(0, 10)}.xlsx`);
      toast("Planilha de materiais exportada em ordem alfabética e por tamanho.");
    } catch (error) {
      console.error("Falha na exportação de materiais", error);
      toast("Não foi possível gerar a planilha de materiais.", true);
    }
  }

  function replaceButton(id, newId, label, handler) {
    const current = document.getElementById(id);
    if (!current) return null;
    const replacement = current.cloneNode(true);
    replacement.id = newId;
    replacement.textContent = label;
    current.replaceWith(replacement);
    replacement.addEventListener("click", handler);
    return replacement;
  }

  function applyPatch() {
    if (window.__SESE_EXCEL_REPORT_PATCH_APPLIED__) return;
    window.__SESE_EXCEL_REPORT_PATCH_APPLIED__ = true;
    replaceButton("exportMaterialsPdf", "exportStockReportExcel", "Relatório Excel", exportStockReportExcelPatch);
    replaceButton("exportMaterials", "exportMaterials", "Exportar Excel", exportMaterialsSortedPatch);
  }

  setTimeout(applyPatch, 0);
})();
